create extension if not exists pgcrypto;
create table if not exists public.courts(id uuid primary key default gen_random_uuid(),name text not null unique,hourly_rate numeric(10,2) not null default 300,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.bookings(id uuid primary key default gen_random_uuid(),booking_code text not null unique,customer_name text not null,customer_mobile text not null,customer_email text not null,proof_path text,total_hours integer not null default 0,total_amount numeric(10,2) not null default 0,payment_status text not null default 'unpaid' check(payment_status in('unpaid','pending_verification','paid','refunded')),booking_status text not null default 'pending' check(booking_status in('pending','confirmed','cancelled','completed')),created_at timestamptz not null default now());
create table if not exists public.booking_slots(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id) on delete cascade,court_id uuid not null references public.courts(id),booking_date date not null,start_minute integer not null check(start_minute between 0 and 1439),end_minute integer not null check(end_minute between 0 and 1439),hourly_rate numeric(10,2) not null,status text not null default 'pending' check(status in('pending','confirmed','cancelled','completed')),created_at timestamptz not null default now());
create unique index if not exists uniq_active_slot on public.booking_slots(court_id,booking_date,start_minute) where status in('pending','confirmed');
insert into public.courts(name,hourly_rate,is_active) values('UNO Court',300,true),('DOS Court',300,true) on conflict(name) do nothing;
insert into storage.buckets(id,name,public) values('payment-proofs','payment-proofs',false) on conflict(id) do nothing;
